'use strict';
document.documentElement.classList.add('js');
const menu=document.querySelector('.menu'),nav=document.querySelector('#nav');
function closeMenu(){nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){closeMenu();menu.focus()}});document.addEventListener('click',e=>{if(!e.target.closest('header'))closeMenu()});
if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.06});document.querySelectorAll('.reveal').forEach(e=>observer.observe(e))}else document.querySelectorAll('.reveal').forEach(e=>e.classList.add('visible'));
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});let count=0;document.querySelectorAll('[data-category]').forEach(p=>{p.hidden=button.dataset.filter!=='all'&&p.dataset.category!==button.dataset.filter;if(!p.hidden){count++;p.classList.add('visible')}});document.querySelector('#filter-status').textContent=`${count}件のコンセプトプロジェクト`;}));
const gallery=[...document.querySelectorAll('[data-gallery]')],dialog=document.querySelector('#lightbox');let current=0,lastFocus;
function showPhoto(index){current=(index+gallery.length)%gallery.length;const b=gallery[current];dialog.querySelector('img').src=b.dataset.src;dialog.querySelector('img').alt=b.dataset.caption+'（AI生成の架空住宅）';dialog.querySelector('p').textContent=`${current+1} / ${gallery.length} — ${b.dataset.caption}`}
gallery.forEach((b,i)=>b.addEventListener('click',()=>{lastFocus=b;showPhoto(i);dialog.showModal()}));dialog.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.querySelector('.prev').addEventListener('click',()=>showPhoto(current-1));dialog.querySelector('.next').addEventListener('click',()=>showPhoto(current+1));dialog.addEventListener('close',()=>lastFocus?.focus());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('keydown',e=>{if(e.key==='ArrowRight')showPhoto(current+1);if(e.key==='ArrowLeft')showPhoto(current-1)});
const form=document.querySelector('#contact-form');if(form){form.querySelector('[type=submit]').disabled=false;const date=form.elements.date;const today=new Date();date.min=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`;form.addEventListener('submit',e=>{e.preventDefault();const status=document.querySelector('#form-status');for(const name of ['name','message']){const field=form.elements[name];field.setCustomValidity(field.value.trim().length<(name==='message'?10:1)?'空白以外の文字を入力してください。ご相談内容は10文字以上で入力してください。':'')}if(!form.reportValidity()){status.textContent='入力内容をご確認ください。必須項目または入力形式に誤りがあります。';return}const list=document.querySelector('#review-values');list.replaceChildren();for(const [name,label]of [['name','お名前'],['email','メールアドレス'],['type','ご相談内容'],['message','お話ししたいこと'],['date','ご希望日']]){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=form.elements[name].value||'指定なし';list.append(dt,dd)}form.hidden=true;const review=document.querySelector('#form-review');review.hidden=false;review.setAttribute('tabindex','-1');review.focus();review.scrollIntoView({block:'start'})});form.addEventListener('input',e=>e.target.setCustomValidity?.(''));document.querySelector('#edit-form').addEventListener('click',()=>{document.querySelector('#form-review').hidden=true;form.hidden=false;form.elements.name.focus()})}
